{
  "id": "dither-coverage",
  "title": "Count dither coverage and constrain its region",
  "applies_to": [
    "limited-palette gradients",
    "intentional texture",
    "ordered translucency"
  ],
  "requires": [
    "A tileable threshold matrix, two approved colors and a region mask"
  ],
  "procedure": [
    "Use the 4x4 rank matrix [[0,8,2,10],[12,4,14,6],[3,11,1,9],[15,7,13,5]].",
    "For fraction q, select cells with rank < 16*q when 16*q is integral.",
    "Keep the pattern phase consistent across adjacent regions unless a discontinuity is intentional."
  ],
  "checks": [
    "Coverage is the actual selected-cell count divided by total cells.",
    "The pattern changes only within its semantic mask."
  ],
  "pitfalls": [
    "The local source's example percentage labels are incorrect; count cells instead.",
    "Dither can add noise and is optional; flat clusters may suit an asset better."
  ],
  "sources": [
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
